WITH flattened_attrs AS (SELECT id, effective_from, tier_prices, AGGREGATE(tier_prices, 0.0D, (acc, p) -> acc + p, acc -> ROUND(acc / SIZE(tier_prices), 2)) AS avg_tier_price, ELEMENT_AT(tier_prices, 1) AS entry_price FROM price_tiers) SELECT CASE WHEN avg_tier_price >= 25 THEN 'HIGH' ELSE 'LOW' END AS avg_tier_price_tier, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(entry_price, ARRAY(0.25, 0.5, 0.75)) AS entry_price_quartiles, GROUPING(CASE WHEN avg_tier_price >= 25 THEN 'HIGH' ELSE 'LOW' END) AS grouping_id FROM flattened_attrs GROUP BY CUBE (CASE WHEN avg_tier_price >= 25 THEN 'HIGH' ELSE 'LOW' END) HAVING COUNT(DISTINCT id) < 1000 ORDER BY distinct_ids DESC NULLS LAST;
